<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { Plus, EditPen, Delete, Refresh } from '@element-plus/icons-vue'
import { subjectApi } from '@/api/modules'
import { isReported } from '@/api/http'
import type { Subject } from '@/types'
const rows = ref<Subject[]>([])
const loading = ref(false)
const dialog = ref(false)
const editingId = ref<number | null>(null)
const form = reactive({ name: '', description: '', status: 1, sort: 1 })
async function load() { loading.value = true; try { rows.value = await subjectApi.list({ enabledOnly: false }) || [] } finally { loading.value = false } }
function openCreate() { editingId.value = null; Object.assign(form, { name: '', description: '', status: 1, sort: 1 }); dialog.value = true }
function openEdit(row: Subject) { editingId.value = row.id; Object.assign(form, row); dialog.value = true }
async function save() { if (!form.name.trim()) return ElMessage.warning('请填写学科名称'); try { if (editingId.value) await subjectApi.update(editingId.value, form); else await subjectApi.create(form); ElMessage.success('学科信息已保存'); dialog.value = false; await load() } catch (e) { if (!isReported(e)) ElMessage.error(e instanceof Error ? e.message : '保存失败') } }
async function remove(row: Subject) { try { await ElMessageBox.confirm(`确定删除学科“${row.name}”吗？如果已有题目关联该学科，后端可能拒绝删除。`, '删除学科', { type: 'warning' }); await subjectApi.remove(row.id); ElMessage.success('已删除'); await load() } catch { /* cancelled */ } }
onMounted(load)
</script>
<template><div class="page-content"><div class="page-title-row"><div><div class="eyebrow">FOUNDATION SETTINGS</div><h1>学科管理</h1><p>维护课程级分类，为题库、知识点和学习分析提供统一维度。</p></div><div class="title-actions"><el-button :icon="Refresh" @click="load">刷新</el-button><el-button type="primary" :icon="Plus" @click="openCreate">新增学科</el-button></div></div><div class="stats-grid compact-stats"><div class="metric-card"><div class="metric-top"><span>学科总数</span><span class="metric-icon blue">01</span></div><div class="metric-value">{{ rows.length }}<small>门</small></div><div class="metric-foot">已配置学科</div></div><div class="metric-card"><div class="metric-top"><span>正常使用</span><span class="metric-icon green">02</span></div><div class="metric-value">{{ rows.filter(r => r.status === 1).length }}<small>门</small></div><div class="metric-foot">状态正常的学科</div></div><div class="metric-card"><div class="metric-top"><span>基础配置</span><span class="metric-icon purple">03</span></div><div class="metric-value">统一</div><div class="metric-foot">供题库和知识点复用</div></div></div><section class="surface-card data-card"><div class="table-toolbar"><div><h3>学科列表</h3><p>点击编辑可维护学科描述、状态和排序</p></div></div><el-table :data="rows" v-loading="loading" stripe empty-text="暂无学科数据"><el-table-column prop="id" label="ID" width="90"/><el-table-column prop="name" label="学科名称" min-width="220"><template #default="scope"><strong>{{ scope.row.name }}</strong></template></el-table-column><el-table-column prop="description" label="描述" min-width="260"><template #default="scope">{{ scope.row.description || '—' }}</template></el-table-column><el-table-column prop="sort" label="排序" width="100"/><el-table-column label="状态" width="120"><template #default="scope"><el-tag :type="scope.row.status === 1 ? 'success' : 'info'">{{ scope.row.status === 1 ? '正常' : '已停用' }}</el-tag></template></el-table-column><el-table-column label="操作" width="160"><template #default="scope"><el-button text type="primary" :icon="EditPen" @click="openEdit(scope.row)">编辑</el-button><el-button text type="danger" :icon="Delete" @click="remove(scope.row)">删除</el-button></template></el-table-column></el-table></section><el-dialog v-model="dialog" :title="editingId ? '编辑学科' : '新增学科'" width="520px"><el-form label-position="top"><el-form-item label="学科名称" required><el-input v-model="form.name" maxlength="100"/></el-form-item><el-form-item label="描述"><el-input v-model="form.description" type="textarea" :rows="3" maxlength="500"/></el-form-item><div class="form-two-cols"><el-form-item label="排序"><el-input-number v-model="form.sort" :min="0" :max="9999"/></el-form-item><el-form-item label="状态"><el-select v-model="form.status"><el-option label="正常" :value="1"/><el-option label="停用" :value="0"/></el-select></el-form-item></div></el-form><template #footer><el-button @click="dialog = false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
